def is_samepatterns(strs, patterns):
    # Create a dictionary to map each character in patterns to a unique character in strs
    d = {}

    # Iterate over the characters in patterns and strs simultaneously
    for i, j in zip(patterns, strs):
        # If the character in patterns is already a key in the dictionary
        if i in d:
            # Check if the corresponding value matches the character in strs
            if d[i] != j:
                return False
        else:
            # If the character in patterns is not a key in the dictionary, add it with the character in strs as the value
            d[i] = j

    # Create a set to ensure all values in the dictionary are unique
    return len(set(d.values())) == len(d.values())

