def check_integer(s):
    # Remove leading and trailing whitespaces
    s = s.strip()

    # Check if the string is empty after stripping
    if len(s) < 1:
        return None

    else:
        # Check if all characters are digits or if the string is a valid negative integer
        if s.isdigit() or (s[0] == '-' and s[1:].isdigit()):
            return True
        else:
            return False

