def sequential_search(arr, elem):
    # Iterate through the array
    for i in range(len(arr)):
        # Check if the current element matches the target element
        if arr[i] == elem:
            # Return True and the current index if the element is found
            return (True, i)
    # Return False and -1 if the element is not found
    return (False, -1)

