def dict_depth(d):
    # Base case: if the input is not a dictionary or is empty, the depth is 0
    if not isinstance(d, dict) or not d:
        return 0
    # Recursive case: calculate the depth of each value in the dictionary
    return 1 + (max(map(dict_depth, d.values())) if d else 0)

# Test the function with the provided test case
assert dict_depth({'a': 1, 'b': {'c': {'d': {}}}}) == 4
